from pathlib import Path
import re

p = Path('index.html')
s = p.read_text(encoding='utf-8')

start = '/* COPAFEM PREMIUM FINAL */'
end = '/* END COPAFEM PREMIUM FINAL */'
s = re.sub(re.escape(start) + r'.*?' + re.escape(end), '', s, flags=re.S)

LOGO = 'data:image/webp;base64,[... ELLIPSIZATION ...]'

css = r'''
/* COPAFEM PREMIUM FINAL */
.premium-gateway{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:28px 18px 42px;background:linear-gradient(135deg,#fffdf8,#f6ead0 46%,#d8be7d 75%,#173e72);color:#163d70}
.premium-gateway[hidden]{display:none!important}
.premium-shell{position:relative;width:min(930px,96vw);min-height:min(900px,94vh);border:1.5px solid rgba(197,148,52,.72);border-radius:34px;background:rgba(255,255,255,.96);box-shadow:0 28px 80px rgba(13,43,78,.20);padding:42px 54px 62px;text-align:center;display:flex;flex-direction:column;align-items:center}
.premium-logo-wrap{width:min(340px,58vw);aspect-ratio:1;border-radius:50%;padding:6px;background:linear-gradient(145deg,#f4d58a,#b9862d,#f9e4aa);box-shadow:0 14px 30px rgba(83,61,23,.16);margin:0 auto 26px;overflow:hidden}
.premium-logo{width:100%;height:100%;display:block;border-radius:50%;object-fit:cover;background:#fff}
.premium-title{font-family:Georgia,'Times New Roman',serif;font-size:clamp(36px,5.5vw,62px);font-weight:700;letter-spacing:.025em;line-height:1.05;margin:0;color:#123b70}
.premium-divider{width:min(620px,82%);height:28px;display:flex;align-items:center;gap:14px;margin:7px 0 6px;color:#c59434;font-size:25px}.premium-divider::before,.premium-divider::after{content:"";height:1.5px;flex:1;background:linear-gradient(90deg,transparent,#c59434)}.premium-divider::after{background:linear-gradient(90deg,#c59434,transparent)}
.premium-subtitle{max-width:690px;margin:0 auto 31px;color:#56708c;font-size:clamp(18px,2.3vw,25px);line-height:1.45}
.premium-player-btn{width:min(720px,92%);min-height:92px;border:2px solid #d7aa51;border-radius:23px;background:linear-gradient(105deg,#082d59,#123f75 48%,#245b91);box-shadow:0 15px 30px rgba(13,43,78,.20);color:#fff;font-size:clamp(24px,3.4vw,37px);font-weight:900;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:20px}.premium-player-btn .arrow{color:#e4bd65;font-size:44px}
.premium-admin-btn{margin-top:24px;border:0;background:transparent;color:#496b91;font-size:clamp(18px,2.2vw,24px);font-weight:850;cursor:pointer;padding:12px 24px;display:flex;align-items:center;gap:12px}.premium-admin-line{display:flex;align-items:center;width:min(480px,76%);gap:14px;justify-content:center}
.premium-gateway .login-card{position:absolute;z-index:20;left:50%;top:50%;transform:translate(-50%,-50%);width:min(470px,calc(100vw - 34px));background:#fff;border:1px solid #d7b46a;border-radius:24px;box-shadow:0 28px 80px rgba(9,34,67,.30);padding:28px;text-align:left}
@media(max-width:700px){.premium-gateway{padding:12px 8px 34px;align-items:flex-start}.premium-shell{width:100%;min-height:calc(100vh - 24px);padding:28px 16px 50px;border-radius:25px}.premium-logo-wrap{width:min(285px,72vw)}.premium-player-btn{width:100%;min-height:72px;font-size:25px}}
/* END COPAFEM PREMIUM FINAL */
'''
s = s.replace('</style>', css + '\n</style>', 1)

gateway = f'''
<section id="roleGateway" class="premium-gateway">
  <div class="premium-shell">
    <div class="premium-logo-wrap"><img class="premium-logo" src="{LOGO}" alt="Logo COPAFEM"></div>
    <h1 class="premium-title">COPAFEM AMERICANOS</h1>
    <div class="premium-divider" aria-hidden="true">♡</div>
    <p class="premium-subtitle">Ingresá a tu torneo y consultá tus partidos,<br>horarios, resultados y el Drop completo.</p>
    <button id="choosePlayer" class="premium-player-btn" type="button"><span>SOY JUGADOR</span><span class="arrow">›</span></button>
    <div class="premium-admin-line"><button id="chooseAdmin" class="premium-admin-btn" type="button"><span>⚙</span><span>ADMINISTRADOR</span></button></div>
    <div id="adminLogin" class="login-card" hidden>
      <h2>Acceso administrador</h2><p>Ingresá la contraseña para abrir el panel de organización.</p>
      <form id="adminLoginForm"><label>Contraseña<input id="adminPassword" type="password" autocomplete="current-password" required placeholder="Contraseña de administrador"></label><div class="login-actions"><button class="btn primary" type="submit">Ingresar</button><button id="cancelAdminLogin" class="btn" type="button">Volver</button></div><div id="adminLoginError" class="login-error" aria-live="polite"></div></form>
    </div>
  </div>
</section>
'''
pattern = r'<section id="roleGateway"[^>]*>.*?</section>\s*(?=<section id="playerApp")'
s, n = re.subn(pattern, gateway + '\n', s, count=1, flags=re.S)
if n != 1:
    raise SystemExit('No se pudo localizar roleGateway')
p.write_text(s, encoding='utf-8')
print('Logo real COPAFEM aplicado')
